// Gate-fixture ffprobe blobs (synthetic verbatim facts — the same shapes
// TestPackGate judges): an opt-in HEVC MKV the knob gates, and a gate-open
// h264/aac MKV the pack lane may always serve.
const (
	gateFfOptIn = `{"streams":[{"codec_type":"video","codec_name":"hevc","pix_fmt":"yuv420p10le"},{"codec_type":"audio","codec_name":"aac"}],"format":{"format_name":"matroska,webm"}}`
	gateFfOpen  = `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"},{"codec_type":"audio","codec_name":"aac"}],"format":{"format_name":"matroska,webm"}}`
)

// gateSeedStore opens a fresh store and seeds one library with the given
// items (id → document).
func gateSeedStore(t *testing.T, docs map[string]map[string]any) (*store.Store, context.Context) {
	t.Helper()
	ctx := context.Background()
	st, err := store.Open(ctx, filepath.Join(t.TempDir(), "gate.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })
	libID, err := st.CreateLibrary(ctx, "tv", "/media/gate", "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	for id, doc := range docs {
		raw, err := json.Marshal(doc)
		if err != nil {
			t.Fatalf("marshal doc %s: %v", id, err)
		}
		if err := st.PutItem(ctx, store.Item{
			ID: id, ModuleID: "tv", LibraryID: libID, FileID: id,
			RelativePath: id + ".mkv", MediaType: "tv",
			Document: raw, SchemaVersion: 1,
		}); err != nil {
			t.Fatalf("PutItem %s: %v", id, err)
		}
	}
	return st, ctx
}

// gateStreamsDoc builds an item document whose streams namespace carries the
// given packaging state and nonce beside the given ffprobe facts.
func gateStreamsDoc(ff, state, nonce string) map[string]any {
	streams := map[string]any{"state": state}
	if nonce != "" {
		streams["nonce"] = nonce
	}
	var facts map[string]any
	if err := json.Unmarshal([]byte(ff), &facts); err != nil {
		panic("bad ffprobe fixture: " + err.Error())
	}
	return map[string]any{"ffprobe": facts, "streams": streams}
}

// TestPlayRetryGate is the acceptance test for the enqueue-site retry gate
// (playback-capability-gate 1.2, D4): the POST /play retry closure consults
// PackGate before EnqueuePack — a knob-off opt-in item refuses with its own
// state_reason token and enqueues nothing, the same item with the knob on
// re-enqueues and answers the 202 shape, a gate-open item behaves exactly as
// before, and nothing-failed still reads (false, nil). A refusal writes no
// ledger row.
func TestPlayRetryGate(t *testing.T) {
	st, ctx := gateSeedStore(t, map[string]map[string]any{
		"it_optin": gateStreamsDoc(gateFfOptIn, "failed", "n1"),
		"it_open":  gateStreamsDoc(gateFfOpen, "failed", "n1"),
		"it_none":  gateStreamsDoc(gateFfOpen, "none", ""),
	})

	// enqueue records every observed enqueue; the stub means no build ever
	// runs, so any ledger row on this path could only come from the closure
	// itself — the hard negative below reads the real store.
	enqueued := []string{}
	enqueue := func(id string) error { enqueued = append(enqueued, id); return nil }

	row := func(id string) store.Item {
		t.Helper()
		r, err := st.GetItem(ctx, id, access.System())
		if err != nil {
			t.Fatalf("GetItem %s: %v", id, err)
		}
		return r
	}

	t.Run("knob_off_optin_refuses_with_its_token", func(t *testing.T) {
		enqueued = nil
		queued, err := retryFailedPack(ctx, st, enqueue, row("it_optin"), false)
		if queued {
			t.Fatal("queued = true, want false for a knob-off opt-in item")
		}
		var gateRefusal refusal.PlayRefusal
		if !errors.As(err, &gateRefusal) {
			t.Fatalf("err = %v, want refusal.PlayRefusal", err)
		}
		if gateRefusal.Reason != "codec_not_opted_in" {
			t.Errorf("Reason = %q, want codec_not_opted_in (the descriptor's own token)", gateRefusal.Reason)
		}
		if len(enqueued) != 0 {
			t.Errorf("enqueued = %v, want nothing on a refusal", enqueued)
		}
		// Hard negative (D4): a policy refusal never poisons — no pack_failed
		// ledger row may exist for the refused item.
		failures, err := st.ListFailures(ctx)
		if err != nil {
			t.Fatalf("ListFailures: %v", err)
		}
		if len(failures) != 0 {
			t.Errorf("ledger rows = %d, want 0 — a refusal must never write one", len(failures))
		}
		// INV4: the refusal names the policy verdict, never a credential.
		if strings.Contains(gateRefusal.Error(), "token") {
			t.Errorf("refusal message %q carries credential-shaped material", gateRefusal.Error())
		}
	})

	t.Run("knob_on_same_item_reenqueues_202_shape", func(t *testing.T) {
		enqueued = nil
		queued, err := retryFailedPack(ctx, st, enqueue, row("it_optin"), true)
		if !queued || err != nil {
			t.Fatalf("retry = (%v, %v), want (true, nil) — the 202 shape", queued, err)
		}
		if len(enqueued) != 1 || enqueued[0] != "it_optin" {
			t.Errorf("enqueued = %v, want exactly it_optin re-enqueued", enqueued)
		}
	})

	t.Run("gate_open_item_unchanged", func(t *testing.T) {
		enqueued = nil
		queued, err := retryFailedPack(ctx, st, enqueue, row("it_open"), false)
		if !queued || err != nil {
			t.Fatalf("retry = (%v, %v), want (true, nil) — a capable item retries exactly as today", queued, err)
		}
		if len(enqueued) != 1 || enqueued[0] != "it_open" {
			t.Errorf("enqueued = %v, want exactly it_open", enqueued)
		}
	})

	t.Run("nothing_failed_still_false_nil", func(t *testing.T) {
		enqueued = nil
		queued, err := retryFailedPack(ctx, st, enqueue, row("it_none"), false)
		if queued || err != nil {
			t.Fatalf("retry = (%v, %v), want (false, nil) — the nothing_failed answer", queued, err)
		}
		if len(enqueued) != 0 {
			t.Errorf("enqueued = %v, want nothing without a failed run", enqueued)
		}
	})
}

// TestRepackSweepGateRefusal covers the sweep-side case of box 1.2: a
// gate-closed unhealthy item is skipped with exactly ONE INFO refusal line
// naming the token — no enqueue, no ledger row — while a gate-open unhealthy
// item enqueues as before and a healthy one is never a job at all.
func TestRepackSweepGateRefusal(t *testing.T) {
	st, ctx := gateSeedStore(t, map[string]map[string]any{
		"it_refused": gateStreamsDoc(gateFfOptIn, "complete", "n1"),
		"it_openbad": gateStreamsDoc(gateFfOpen, "complete", "n1"),
		"it_openok":  gateStreamsDoc(gateFfOpen, "complete", "n1"),
	})
	root := t.TempDir()
	for _, id := range []string{"it_refused", "it_openbad", "it_openok"} {
		if err := os.MkdirAll(filepath.Join(root, id, "n1"), 0o755); err != nil {
			t.Fatalf("mkdir %s: %v", id, err)
		}
	}

	// The integrity judge: both bad builds break, the healthy one passes.
	validate := func(itemID, _ string) error {
		if itemID == "it_openok" {
			return nil
		}
		return errors.New("segment missing")
	}

	enqueued := []string{}
	enqueue := func(id string) error { enqueued = append(enqueued, id); return nil }

	var buf bytes.Buffer
	prev := slog.Default()
	slog.SetDefault(slog.New(slog.NewTextHandler(&buf, nil)))
	t.Cleanup(func() { slog.SetDefault(prev) })

	sweepIntegrity(ctx, st, root, validate, enqueue, false)

	if len(enqueued) != 1 || enqueued[0] != "it_openbad" {
		t.Errorf("enqueued = %v, want exactly it_openbad (the gate-open broken build)", enqueued)
	}
	// One INFO refusal line, naming the item and the gate token.
	lines := strings.Split(strings.TrimSpace(buf.String()), "\n")
	refusals := 0
	for _, line := range lines {
		if strings.Contains(line, "repack refused by pack gate") {
			refusals++
			if !strings.Contains(line, "it_refused") || !strings.Contains(line, "codec_not_opted_in") {
				t.Errorf("refusal line = %q, want the item and the codec_not_opted_in token", line)
			}
		}
		if strings.Contains(line, "it_refused") && strings.Contains(line, "fronted repack") {
			t.Errorf("refused item fronted anyway: %q", line)
		}
	}
	if refusals != 1 {
		t.Errorf("refusal lines = %d, want exactly 1 (buf = %s)", refusals, buf.String())
	}
	// Hard negative: the sweep's refusal never reaches the failure ledger —
	// the enqueue is a stub, so any row here could only be the sweep's own
	// write, and there must be none.
	failures, err := st.ListFailures(ctx)
	if err != nil {
		t.Fatalf("ListFailures: %v", err)
	}
	if len(failures) != 0 {
		t.Errorf("ledger rows = %d, want 0 — the sweep must refuse without one", len(failures))
	}
}

// TestPackItemGateRefusal covers the build-time gate (playback-capability-gate
// 1.3, D4): the PackItem closure consults packGateRefusal BEFORE Pack — a
// knob-off opt-in item returns refusal.PolicyRefusal carrying the gate's
// state_reason token and Pack is never called, while a knob-enabled opt-in
// item and a gate-open item reach Pack exactly as before.
func TestPackItemGateRefusal(t *testing.T) {
	facts := func(t *testing.T, ff string) map[string]any {
		t.Helper()
		var m map[string]any
		if err := json.Unmarshal([]byte(ff), &m); err != nil {
			t.Fatalf("unmarshal ffprobe fixture: %v", err)
		}
		return m
	}

	packed := false
	pack := func() error { packed = true; return nil }
	closure := func(ff map[string]any, optInCodecs bool) error {
		if err := packGateRefusal(ff, optInCodecs); err != nil {
			return err
		}
		return pack()
	}

	t.Run("knob_off_optin_refuses_before_pack", func(t *testing.T) {
		packed = false
		err := closure(facts(t, gateFfOptIn), false)
		var policyRefusal refusal.PolicyRefusal
		if !errors.As(err, &policyRefusal) {
			t.Fatalf("err = %v, want refusal.PolicyRefusal", err)
		}
		if policyRefusal.Reason != "codec_not_opted_in" {
			t.Errorf("Reason = %q, want codec_not_opted_in (the descriptor's own token)", policyRefusal.Reason)
		}
		if packed {
			t.Error("Pack was called on a gate-closed item — the closure must refuse before it")
		}
	})

	t.Run("knob_on_optin_packs", func(t *testing.T) {
		packed = false
		if err := closure(facts(t, gateFfOptIn), true); err != nil {
			t.Fatalf("err = %v, want nil — the knob enables the opt-in codecs", err)
		}
		if !packed {
			t.Error("Pack was not called for a knob-enabled item")
		}
	})

	t.Run("gate_open_packs_unchanged", func(t *testing.T) {
		packed = false
		if err := closure(facts(t, gateFfOpen), false); err != nil {
			t.Fatalf("err = %v, want nil — a capable item packs exactly as before", err)
		}
		if !packed {
			t.Error("Pack was not called for a gate-open item")
		}
	})
}

// TestPlayLazyRepack is the acceptance test for the lazy re-heal decision
// (pack-manifest-audio 3.1, D5; re-versioned by fix-tv-unblock-2 Interfaces
// 2): a stale build — state complete, a build nonce, a rule version older
// than pack.MasterRuleVersion (absent = v0, boolean true = the legacy v1
// write) — enqueues exactly ONE repack through the ordinary pack-on-play
// path and answers the 202 shape; a current (version-carrying) build — and a
// FUTURE one, so an older constant never re-heals a newer build — never
// re-enqueues and falls through to the ordinary decision; a gate-closed
// stale item (knob-off HEVC) logs ONE "legacy repack skipped" INFO line
// naming the item and the token, enqueues nothing, keeps playing its
// existing build, and writes no ledger row. Both lines hold INV4 (item id
// and refusal token only).
func TestPlayLazyRepack(t *testing.T) {
	st, ctx := gateSeedStore(t, map[string]map[string]any{
		"it_legacy":       gateStreamsDoc(gateFfOpen, "complete", "n1"),
		"it_current":      gateStreamsDoc(gateFfOpen, "complete", "n1"),
		"it_stale_closed": gateStreamsDoc(gateFfOptIn, "complete", "n1"),
		"it_v1_bool":      gateStreamsDoc(gateFfOpen, "complete", "n1"),
		"it_future":       gateStreamsDoc(gateFfOpen, "complete", "n1"),
	})
	// it_current carries the version the success persist writes (the enrich
	// streams lane); it_v1_bool carries the LEGACY boolean-true write (v1 —
	// stale under the current constant); it_future carries a version newer
	// than this binary's constant; the legacy docs stay version-free (v0).
	setMaster := func(id string, master any) {
		t.Helper()
		r := mustRow(t, st, ctx, id)
		doc := decodeItemDoc(r.Document)
		doc["streams"].(map[string]any)["master"] = master
		b, err := json.Marshal(doc)
		if err != nil {
			t.Fatalf("marshal %s: %v", id, err)
		}
		r.Document = b
		if err := st.PutItem(ctx, r); err != nil {
			t.Fatalf("PutItem %s: %v", id, err)
		}
	}
	setMaster("it_current", pack.MasterRuleVersion)
	setMaster("it_v1_bool", true)
	setMaster("it_future", pack.MasterRuleVersion+1)

	enqueued := []string{}
	enqueue := func(id string) error { enqueued = append(enqueued, id); return nil }

	var buf bytes.Buffer
	prev := slog.Default()
	slog.SetDefault(slog.New(slog.NewTextHandler(&buf, nil)))
	t.Cleanup(func() { slog.SetDefault(prev) })

	t.Run("stale_build_enqueues_once_202_shape", func(t *testing.T) {
		buf.Reset()
		enqueued = nil
		queued, err := packOnPlay(ctx, st, enqueue, mustRow(t, st, ctx, "it_legacy"), false)
		if !queued || err != nil {
			t.Fatalf("packOnPlay = (%v, %v), want (true, nil) — the 202 shape", queued, err)
		}
		if len(enqueued) != 1 || enqueued[0] != "it_legacy" {
			t.Errorf("enqueued = %v, want exactly it_legacy, once", enqueued)
		}
		lines := strings.Split(strings.TrimSpace(buf.String()), "\n")
		queuedLines := 0
		for _, line := range lines {
			if strings.Contains(line, "legacy repack queued") {
				queuedLines++
				if !strings.Contains(line, "it_legacy") {
					t.Errorf("queued line = %q, want the item", line)
				}
			}
		}
		if queuedLines != 1 {
			t.Errorf("queued lines = %d, want exactly 1 (buf = %s)", queuedLines, buf.String())
		}
	})

	t.Run("current_build_never_reenqueues", func(t *testing.T) {
		buf.Reset()
		enqueued = nil
		queued, err := packOnPlay(ctx, st, enqueue, mustRow(t, st, ctx, "it_current"), false)
		if queued || err != nil {
			t.Fatalf("packOnPlay = (%v, %v), want (false, nil) — a build at the current version is not stale", queued, err)
		}
		if len(enqueued) != 0 {
			t.Errorf("enqueued = %v, want nothing for a current build", enqueued)
		}
		if strings.Contains(buf.String(), "legacy repack") {
			t.Errorf("log = %q, want no legacy-repack line for a current build", buf.String())
		}
	})

	t.Run("v1_boolean_seed_is_stale", func(t *testing.T) {
		buf.Reset()
		enqueued = nil
		queued, err := packOnPlay(ctx, st, enqueue, mustRow(t, st, ctx, "it_v1_bool"), false)
		if !queued || err != nil {
			t.Fatalf("packOnPlay = (%v, %v), want (true, nil) — boolean true reads v1, stale under the current constant", queued, err)
		}
		if len(enqueued) != 1 || enqueued[0] != "it_v1_bool" {
			t.Errorf("enqueued = %v, want exactly it_v1_bool, once", enqueued)
		}
	})

	t.Run("future_version_seed_stays_put", func(t *testing.T) {
		buf.Reset()
		enqueued = nil
		queued, err := packOnPlay(ctx, st, enqueue, mustRow(t, st, ctx, "it_future"), false)
		if queued || err != nil {
			t.Fatalf("packOnPlay = (%v, %v), want (false, nil) — version ≥ current never enqueues (a future rule must not re-heal)", queued, err)
		}
		if len(enqueued) != 0 {
			t.Errorf("enqueued = %v, want nothing for a future-version build", enqueued)
		}
		if strings.Contains(buf.String(), "legacy repack") {
			t.Errorf("log = %q, want no legacy-repack line for a future build", buf.String())
		}
	})

	t.Run("gate_closed_keeps_playing", func(t *testing.T) {
		buf.Reset()
		enqueued = nil
		queued, err := packOnPlay(ctx, st, enqueue, mustRow(t, st, ctx, "it_stale_closed"), false)
		if queued || err != nil {
			t.Fatalf("packOnPlay = (%v, %v), want (false, nil) — the old build keeps serving", queued, err)
		}
		if len(enqueued) != 0 {
			t.Errorf("enqueued = %v, want nothing on a closed gate", enqueued)
		}
		lines := strings.Split(strings.TrimSpace(buf.String()), "\n")
		skips := 0
		for _, line := range lines {
			if strings.Contains(line, "legacy repack skipped") {
				skips++
				if !strings.Contains(line, "it_stale_closed") || !strings.Contains(line, "codec_not_opted_in") {
					t.Errorf("skip line = %q, want the item and the codec_not_opted_in token", line)
				}
			}
			if strings.Contains(line, "legacy repack queued") {
				t.Errorf("gate-closed item queued anyway: %q", line)
			}
		}
		if skips != 1 {
			t.Errorf("skip lines = %d, want exactly 1 (buf = %s)", skips, buf.String())
		}
		// Hard negative: the skip is a policy verdict, never a pack failure —
		// no pack_failed ledger row may exist.
		failures, err := st.ListFailures(ctx)
		if err != nil {
			t.Fatalf("ListFailures: %v", err)
		}
		if len(failures) != 0 {
			t.Errorf("ledger rows = %d, want 0 — the skip must never write one", len(failures))
		}
	})
}

// TestDescriptorLazyRepack is the acceptance test for the descriptor-path
// lazy repack trigger (repack-descriptor-trigger 1.1): the playback
// descriptor GET — the verb every playback actually hits (the SPA mounts the
// player from the descriptor's play_url) — runs the SAME stale-build
// decision as the play verb. A stale build (state complete + a build nonce,
// a rule version older than pack.MasterRuleVersion) enqueues exactly ONE
// repack through the ordinary EnqueuePack seam while the GET still ANSWERS
// the current old build; a repeated GET while the repack runs is
// lease-absorbed, never re-enqueued per request; a current (version-carrying)
// build never enqueues; a gate-closed stale item logs ONE "legacy repack
// skipped" INFO line naming the item and the token and answers without
// enqueueing. The play verb's own path is unchanged (TestPlayLazyRepack).
// Both lines hold INV4: no media token and no play URL ever ride a captured
// line.
func TestDescriptorLazyRepack(t *testing.T) {
	st, ctx := gateSeedStore(t, map[string]map[string]any{
		"it_legacy":       gateStreamsDoc(gateFfOpen, "complete", "n1"),
		"it_current":      gateStreamsDoc(gateFfOpen, "complete", "n1"),
		"it_stale_closed": gateStreamsDoc(gateFfOptIn, "complete", "n1"),
	})
	// The current build carries the version the success persist writes
	// (internal/enrich streams lane); the legacy docs stay version-free.
	r := mustRow(t, st, ctx, "it_current")
	doc := decodeItemDoc(r.Document)
	doc["streams"].(map[string]any)["master"] = pack.MasterRuleVersion
	b, err := json.Marshal(doc)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	r.Document = b
	if err := st.PutItem(ctx, r); err != nil {
		t.Fatalf("PutItem it_current: %v", err)
	}

	mediaSvc := &stream.Service{Root: t.TempDir(), Secret: []byte("descriptor-repack-test-secret")}

	// enqueue mirrors the real seam's contract: the closure enqueues
	// unconditionally into EnqueuePack, and the lane's per-item lease absorbs
	// the repeats — a held item's re-enqueue is dropped here exactly as the
	// lease drops a task whose item's run is pending or running.
	var enqueued []string
	held := map[string]bool{}
	enqueue := func(id string) error {
		if held[id] {
			return nil // the lease: the pending/running repack owns the item
		}
		held[id] = true
		enqueued = append(enqueued, id)
		return nil
	}

	var buf bytes.Buffer
	prev := slog.Default()
	slog.SetDefault(slog.New(slog.NewTextHandler(&buf, nil)))
	t.Cleanup(func() { slog.SetDefault(prev) })

	// describe drives the real api.Deps.Playback closure body once.
	describe := func(t *testing.T, id string, optIn bool) api.Playback {
		t.Helper()
		pb, err := playbackDescriptor(ctx, st, mediaSvc, enqueue, optIn, id)
		if err != nil {
			t.Fatalf("playbackDescriptor(%s): %v", id, err)
		}
		return pb
	}
	// countLines counts the captured lines whose msg names the given phrase.
	countLines := func(phrase string) int {
		n := 0
		for _, ln := range strings.Split(strings.TrimSpace(buf.String()), "\n") {
			if strings.Contains(ln, phrase) {
				n++
			}
		}
		return n
	}

	t.Run("stale_build_enqueues_once_and_still_answers", func(t *testing.T) {
		buf.Reset()
		enqueued = nil
		held = map[string]bool{}
		pb := describe(t, "it_legacy", false)
		if len(enqueued) != 1 || enqueued[0] != "it_legacy" {
			t.Errorf("enqueued = %v, want exactly it_legacy, once", enqueued)
		}
		if queued := countLines("legacy repack queued"); queued != 1 {
			t.Errorf("queued lines = %d, want exactly 1 (buf = %s)", queued, buf.String())
		}
		// The GET answers the current old build while the repack runs: the
		// answer is unchanged — a playable play_url still rides back.
		if pb.PlayURL == "" {
			t.Error("play_url = empty, want the descriptor to still answer the old build")
		}
		// A repeated GET while the repack runs is lease-absorbed: still
		// exactly one enqueue, and the answer again.
		pb2 := describe(t, "it_legacy", false)
		if len(enqueued) != 1 {
			t.Errorf("enqueued = %v after a repeat GET, want the lease to absorb it", enqueued)
		}
		if pb2.PlayURL == "" {
			t.Error("repeat GET play_url = empty, want the old build again")
		}
		// INV4: no captured line ever carries the media token or the play URL.
		if strings.Contains(buf.String(), pb.Token) {
			t.Errorf("log = %q carries the media token", buf.String())
		}
		if strings.Contains(buf.String(), pb.PlayURL) {
			t.Errorf("log = %q carries the play URL", buf.String())
		}
	})

	t.Run("current_build_never_enqueues", func(t *testing.T) {
		buf.Reset()
		enqueued = nil
		pb := describe(t, "it_current", false)
		if len(enqueued) != 0 {
			t.Errorf("enqueued = %v, want nothing for a current-version build", enqueued)
		}
		if strings.Contains(buf.String(), "legacy repack") {
			t.Errorf("log = %q, want no legacy-repack line for a current build", buf.String())
		}
		if pb.PlayURL == "" {
			t.Error("play_url = empty, want the descriptor to answer as before")
		}
	})

	t.Run("gate_closed_answers_without_enqueue", func(t *testing.T) {
		buf.Reset()
		enqueued = nil
		pb := describe(t, "it_stale_closed", false) // the opt-in knob is off
		if len(enqueued) != 0 {
			t.Errorf("enqueued = %v, want nothing on a closed gate", enqueued)
		}
		if skips := countLines("legacy repack skipped"); skips != 1 {
			t.Errorf("skip lines = %d, want exactly 1 (buf = %s)", skips, buf.String())
		}
		for _, ln := range strings.Split(strings.TrimSpace(buf.String()), "\n") {
			if strings.Contains(ln, "legacy repack skipped") &&
				(!strings.Contains(ln, "it_stale_closed") || !strings.Contains(ln, "codec_not_opted_in")) {
				t.Errorf("skip line = %q, want the item and the codec_not_opted_in token", ln)
			}
			if strings.Contains(ln, "legacy repack queued") {
				t.Errorf("gate-closed item queued anyway: %q", ln)
			}
		}
		// The gate-closed GET still answers its existing build.
		if pb.PlayURL == "" {
			t.Error("play_url = empty, want the gate-closed GET to keep answering")
		}
		// Hard negative: the skip is a policy verdict, never a pack failure —
		// no pack_failed ledger row may exist.
		failures, err := st.ListFailures(ctx)
		if err != nil {
			t.Fatalf("ListFailures: %v", err)
		}
		if len(failures) != 0 {
			t.Errorf("ledger rows = %d, want 0 — the skip must never write one", len(failures))
		}
	})
}

// mustRow fetches one seeded item row or fails the test.
func mustRow(t *testing.T, st *store.Store, ctx context.Context, id string) store.Item {
	t.Helper()
	r, err := st.GetItem(ctx, id, access.System())
	if err != nil {
		t.Fatalf("GetItem %s: %v", id, err)
	}
	return r
}
